import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ToolRegistry} from './tools/registry.js';
import {scriptedProvider, registryReturning, TOOL_CALL} from './chatOrchestratorTestFixtures.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

async function runAndCapture(provider: AIProvider, registry?: ToolRegistry): Promise<UsageMetadata | undefined> {
  let captured: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, usage) => {
      captured = usage;
    },
  };
  const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
  await orchestrator.processMessage(createSession('ask'));
  return captured;
}

describe('ChatOrchestrator usage accumulation', () => {
  it('accumulates usage from multiple tool rounds into a sum', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 100, outputTokens: 20, totalTokens: 120};
    const round2Usage: UsageMetadata = {inputTokens: 150, outputTokens: 30, totalTokens: 180};

    const provider = scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
      [
        {type: 'text', text: 'done'},
        {type: 'stop', stopReason: 'end_turn', usage: round2Usage},
      ],
    ]);

    expect(await runAndCapture(provider, registryReturning({result: 'r'}))).toEqual({
      inputTokens: 250,
      outputTokens: 50,
      totalTokens: 300,
    });
  });

  it('reports the single round usage when a turn has no tool calls', async () => {
    const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};

    const provider = scriptedProvider([
      [
        {type: 'text', text: 'answer'},
        {type: 'stop', stopReason: 'end_turn', usage},
      ],
    ]);

    expect(await runAndCapture(provider)).toEqual(usage);
  });

  it('accumulates only from rounds that report usage, handling undefined in some rounds', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 50, outputTokens: 10, totalTokens: 60};
    const round3Usage: UsageMetadata = {inputTokens: 75, outputTokens: 15, totalTokens: 90};

    const provider = scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
      [
        {type: 'text', text: 'done'},
        {type: 'stop', stopReason: 'end_turn', usage: round3Usage},
      ],
    ]);

    expect(await runAndCapture(provider, registryReturning({result: 'r'}))).toEqual({
      inputTokens: 125,
      outputTokens: 25,
      totalTokens: 150,
    });
  });

  it('reports undefined when no rounds report usage', async () => {
    const provider = scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
      [
        {type: 'text', text: 'done'},
        {type: 'stop', stopReason: 'end_turn'},
      ],
    ]);

    expect(await runAndCapture(provider, registryReturning({result: 'r'}))).toBeUndefined();
  });
});

